contract.content:
{
  "action": "execute",
  "archetype": "ai-tool",
  "message": "Building an enterprise knowledge Q&A assistant: employees ask plain-English questions and receive answers with citations drawn from indexed SharePoint documents, internal wikis, and archived project files. Includes document ingestion pipeline (SharePoint primary, manual upload for wikis/archives), RAG-based answering with first-class citations on every response, audit logging of all Q&A, an admin dashboard showing usage/top questions/coverage gaps, and CSV export of Q&A history and citation reports.",
  "flags": ["has-users", "has-admin", "ai-rag", "sharepoint", "exports-csv"],
  "tasks": [
    {
      "scope": "database",
      "summary": "Stores users, ingested documents, asked questions, generated answers, and citation links for audit and admin reporting.",
      "task": "Tables: users, documents, questions, answers, citations. Indexes: FK columns, questions.created_at DESC, documents.source. Column-level contract: data_model.",
      "dockerfile": "Dockerfile.postgres",
      "rules": [],
      "snippets": [],
      "primarySnippet": ""
    },
    {
      "scope": "vectordb",
      "summary": "Stores embedded chunks of enterprise documents so the assistant can retrieve relevant passages for any question.",
      "task": "pgvector extension. Table: doc_chunks(id SERIAL PK, document_id INT, chunk_index INT, content TEXT, embedding vector(3072), metadata JSONB). Index: HNSW on embedding (cosine). Embedding model: text-embedding-3-large via MGA. Retrieval: top-k=8 with similarity scores returned for citation building.",
      "dockerfile": "Dockerfile.pgvector",
      "rules": [],
      "snippets": [],
      "primarySnippet": "vectordb/vectordb-connections.ts"
    },
    {
      "scope": "backend",
      "summary": "Handles questions, runs retrieval-augmented generation against indexed documents, returns cited answers, ingests SharePoint and uploaded documents, and serves admin analytics and CSV exports.",
      "task": "Data: pg Pool from env (postgres + pgvector). Endpoints + bodies: api_contract. Behaviors + rules + side-effects: business_logic_contract. RAG flow: embed question via MGA text-embedding-3-large → top-k retrieve from doc_chunks → call MGA assistant 'default' with passages → parse citations → persist question+answer+citations. Ingestion: SharePoint connector pulls docs (stubbed creds via env), chunk (~800 tokens, 100 overlap), embed, store. Wiki/archive ingestion via manual upload endpoint. Auth: x-amzn-oidc-data JWT sub/email. CSV export streams text/csv.",
      "dockerfile": "Dockerfile.node",
      "rules": [],
      "snippets": [],
      "primarySnippet": "backend/express-server-template.ts"
    },
    {
      "scope": "frontend",
      "summary": "Employee chat interface for asking questions and seeing cited answers, plus an admin dashboard for usage analytics, coverage gaps, and CSV downloads.",
      "task": "Views + components: ui_contract. Endpoints + body shapes: api_contract (prepend /api/). Citations rendered inline under each answer with document title + location, clickable to source. States: spinner during ask, empty CTA on first load, toast on 4xx/5xx, 404 page, disabled submit during POST. Admin dashboard with charts for top questions, citation patterns, coverage gaps. Responsive.",
      "dockerfile": "Dockerfile.react",
      "rules": [],
      "snippets": [],
      "primarySnippet": "frontend/AppScaffold.tsx"
    },
    {
      "scope": "integration",
      "summary": "Wires all services together for local development and deployment.",
      "task": "Wire database, vectordb, backend, frontend. Backend env: DATABASE_HOST=database, DATABASE_PORT=5432, DATABASE_NAME=knowledge_qa, DATABASE_USER=knowledge_qa_user, DATABASE_PASSWORD=localdev123, VECTORDB_HOST=vectordb, VECTORDB_PORT=5433, SHAREPOINT_TENANT/CLIENT_ID/SECRET (stub). nginx.local.conf proxy /api→backend:3000. depends_on chain: database+vectordb → backend → frontend. Healthchecks on each. Named volumes for postgres data.",
      "dockerfile": "",
      "rules": [],
      "snippets": [],
      "primarySnippet": "integration/docker-compose-fullstack.yml"
    }
  ],
  "data_model": {
    "tables": [
      {
        "name": "users",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "oidc_sub", "type": "TEXT UNIQUE NOT NULL"},
          {"name": "email", "type": "VARCHAR(255) NOT NULL"},
          {"name": "role", "type": "VARCHAR(32) NOT NULL DEFAULT 'employee'"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "documents",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "title", "type": "TEXT NOT NULL"},
          {"name": "source", "type": "VARCHAR(32) NOT NULL"},
          {"name": "source_url", "type": "TEXT"},
          {"name": "source_location", "type": "TEXT"},
          {"name": "uploaded_by", "type": "INTEGER REFERENCES users(id)"},
          {"name": "indexed_at", "type": "TIMESTAMPTZ"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "questions",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "user_id", "type": "INTEGER NOT NULL REFERENCES users(id)"},
          {"name": "text", "type": "TEXT NOT NULL"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "answers",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "question_id", "type": "INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE"},
          {"name": "text", "type": "TEXT NOT NULL"},
          {"name": "model", "type": "VARCHAR(64)"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "citations",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "answer_id", "type": "INTEGER NOT NULL REFERENCES answers(id) ON DELETE CASCADE"},
          {"name": "document_id", "type": "INTEGER NOT NULL REFERENCES documents(id)"},
          {"name": "chunk_index", "type": "INTEGER"},
          {"name": "location_label", "type": "TEXT"},
          {"name": "similarity", "type": "REAL"}
        ]
      }
    ]
  },
  "api_contract": {
    "version": 1,
    "endpoints": [
      {"method": "GET", "path": "/whoami", "response": {"status": 200, "body": "{ id, email, role }"}},
      {"method": "POST", "path": "/questions", "request": {"text": "string required"}, "response": {"status": 201, "body": "{ question: { id, text }, answer: { id, text }, citations: [{ document_id, title, source, source_url, location_label, similarity }] }"}},
      {"method": "GET", "path": "/questions", "response": {"status": 200, "body": "[{ id, text, created_at, answer: { id, text }, citations: [...] }]  (paginated ?limit=50&offset=0, newest first)"}},
      {"method": "GET", "path": "/questions/:id", "response": {"status": 200, "body": "{ id, text, created_at, answer, citations }"}},
      {"method": "GET", "path": "/documents", "response": {"status": 200, "body": "[{ id, title, source, source_url, indexed_at }] (paginated, newest first)"}},
      {"method": "POST", "path": "/documents/upload", "request": {"title": "string required", "content": "string required", "source": "string (wiki|archive|manual)", "source_url": "string optional"}, "response": {"status": 201, "body": "{ id, title, source, indexed_at }"}},
      {"method": "POST", "path": "/documents/sync-sharepoint", "request": {"site": "string optional"}, "response": {"status": 202, "body": "{ job_id, started_at }"}},
      {"method": "GET", "path": "/admin/analytics", "response": {"status": 200, "body": "{ total_questions, total_documents, top_questions: [...], top_cited_documents: [...], coverage_gaps: [...] }"}},
      {"method": "GET", "path": "/admin/export/questions.csv", "response": {"status": 200, "body": "text/csv stream"}},
      {"method": "GET", "path": "/admin/export/citations.csv", "response": {"status": 200, "body": "text/csv stream"}}
    ]
  },
  "ui_contract": {
    "primary_view": "ask-a-question chat panel with cited answer below",
    "primary_action": "ask a question in plain English",
    "secondary_views": ["question history", "document library", "admin analytics dashboard", "admin exports"],
    "components": [
      {"name": "QuestionBox", "role": "plain-English question input with submit"},
      {"name": "AnswerCard", "role": "displays generated answer text"},
      {"name": "CitationList", "role": "lists source citations under each answer with title, location, and link"},
      {"name": "QuestionHistory", "role": "user's past questions and answers, paginated"},
      {"name": "DocumentLibrary", "role": "lists indexed documents with source label"},
      {"name": "DocumentUploadForm", "role": "manual upload for wiki and archive content"},
      {"name": "SharePointSyncButton", "role": "triggers SharePoint ingestion job"},
      {"name": "AdminDashboard", "role": "usage stats, top questions, citation patterns, coverage gaps"},
      {"name": "CoverageGapsPanel", "role": "highlights questions with weak or no citations"},
      {"name": "ExportButtons", "role": "download Q&A and citations CSVs"}
    ]
  },
  "business_logic_contract": {
    "triggers": [
      {"event": "user_first_login", "action": "create users row from OIDC claims (sub, email); default role='employee'"},
      {"event": "question_submitted", "action": "embed via MGA, retrieve top-k chunks from vectordb, call MGA assistant with passages, persist question+answer+citations, return cited answer"},
      {"event": "document_uploaded", "action": "chunk text, embed via MGA text-embedding-3-large, store chunks in vectordb, set documents.indexed_at"},
      {"event": "sharepoint_sync_triggered", "action": "fetch documents from configured SharePoint sites, ingest each as a document, chunk+embed+index"}
    ],
    "rules": [
      "employees can only see their own question history",
      "all users can view the document library and ask questions",
      "/admin/* endpoints require role='admin'",
      "every answer MUST include at least one citation referencing a document_id; if retrieval yields no relevant passages, answer states 'no source found' and is flagged as coverage gap",
      "CSV exports are admin-only",
      "users cannot delete or modify others' questions"
    ],
    "side_effects": [
      "audit log on every write (questions, answers, document ingestion, sharepoint sync, exports)",
      "coverage gap recorded when a question's top retrieval similarity falls below threshold"
    ]
  },
  "vector_engine": "pgvector",
  "mga_assistants": [
    {
      "key": "default",
      "name": "Enterprise Knowledge Assistant",
      "description": "Answers employee questions in plain English using indexed enterprise documents from SharePoint, wikis, and archived project files. Every answer includes citations linking back to source documents so users can verify and discover existing initiatives, lessons learned, and prior deliverables.",
      "model": "claude-opus-4.7",
      "tool_keys": [],
      "starter_messages": [
        "Have we done a similar initiative before?",
        "What lessons learned exist for client onboarding projects?",
        "Find prior deliverables related to supply chain analytics."
      ],
      "instructions": "Always ground answers in retrieved passages. Cite every claim with document title and location. If retrieved context is insufficient, say so explicitly rather than guessing."
    }
  ]
}
